'use strict';

// Reads item parameters and responses generated by the WLE section of
// jsCAT-validation.Rmd, runs jsCAT WLE for every person, and writes
// the theta estimates to validation/data/wle_jscat.csv.
//
// Prerequisites:
//   1. npm run build (from repo root)
//   2. Run the "WLE Estimator Validation" chunks in jsCAT-validation.Rmd
//      to produce validation/data/wle_items.csv and wle_responses.csv

const { Cat } = require('../../lib/index.js');
const fs = require('fs');
const path = require('path');

function parseCSV(filepath) {
  const lines = fs.readFileSync(filepath, 'utf8').trim().split('\n');
  const headers = lines[0].split(',').map(h => h.replace(/^"|"$/g, '').trim());
  return lines.slice(1).map(line => {
    const vals = line.split(',').map(v => v.replace(/^"|"$/g, '').trim());
    return Object.fromEntries(headers.map((h, i) => [h, vals[i] !== undefined ? vals[i] : '']));
  });
}

const dataDir = path.join(__dirname, '..', 'data');
const items = parseCSV(path.join(dataDir, 'wle_items.csv'));
const responses = parseCSV(path.join(dataDir, 'wle_responses.csv'));

const zetas = items.map(item => ({
  a: parseFloat(item.a),
  b: parseFloat(item.b),
  c: parseFloat(item.c),
  d: parseFloat(item.d),
}));

const itemCols = Object.keys(responses[0]);

const results = responses.map((respRow, i) => {
  const cat = new Cat({ method: 'WLE', minTheta: -6, maxTheta: 6 });
  const answers = zetas.map((_, j) => parseInt(respRow[itemCols[j]]));
  cat.updateAbilityEstimate(zetas, answers);
  return { pid: i + 1, jscat_wle: cat.theta };
});

const csv = ['pid,jscat_wle', ...results.map(r => `${r.pid},${r.jscat_wle}`)].join('\n');
fs.writeFileSync(path.join(dataDir, 'wle_jscat.csv'), csv);
console.log(`Written ${results.length} WLE estimates to validation/data/wle_jscat.csv`);
